export function setupHelp(navigate){const root=document.getElementById('help-screen');let role='',step=0,practice=0;
 const stock=()=>['estoquista','admin'].includes(role);
 function lessons(){return [{icon:'⌕',title:'Encontre o produto',text:'Digite a descrição, marca ou código na Consulta produtos. Pequenos erros de digitação também são aceitos. Confira unidade, preço, promoção e a data da leitura da planilha.',action:'Abrir consulta',view:'products'},{icon:'▤',title:stock()?'Abra a fila de reposição':'Monte a sua lista',text:stock()?'Em Reposição, filtre as listas por situação e corredor. Itens para cliente esperando ficam destacados. Abra uma lista e clique em Iniciar separação para identificar quem está atendendo.':'Escolha o corredor, localize o produto, informe quantidade e embalagem e adicione à lista. Só use Para cliente esperando quando for urgente. Revise e envie a lista inteira.',action:'Abrir reposição',view:'restock'},{icon:'□',title:stock()?'Separe e confirme':'Acompanhe o pedido',text:stock()?'Separe os itens. Se houver apenas parte da quantidade, informe o que foi separado e salve. Depois toque em Confirmar lista pronta: itens sem quantidade informada contam como separados por completo.':'Você pode editar ou excluir sua lista enquanto ela estiver pendente. Em separação, a edição fica bloqueada. Quando estiver pronta, confira as faltas e vá buscar. Duplicar lista cria um novo rascunho.',action:'Ver listas',view:'restock'},{icon:'%',title:'Prepare um orçamento',text:'Na aba Orçamentos, bipe ou busque os produtos. Ajuste quantidade e desconto de cada item, aplique um desconto geral em % ou R$, preencha os dados do cliente, a validade e a observação. Imprima ou salve em PDF. Isso não reserva produtos e não envia uma lista ao estoque.',action:'Criar orçamento',view:'quotes'},{icon:'▥',title:'Entenda as solicitações',text:'Em Relatórios, escolha as datas e gere o ranking. Produtos são agrupados por embalagem, sem somar caixas com unidades. Vendedores e repositores veem suas próprias listas; estoque e administração veem a equipe.',action:'Abrir relatórios',view:'reports'},{icon:'⚙',title:'Personalize e trabalhe offline',text:'Em Configurações, altere nome, usuário e senha. Somente o administrador gerencia cargos, marcas e corredores. Para trabalhar offline, salve o catálogo com internet e use Lista offline e impressão. O rascunho offline nunca é enviado automaticamente.',action:'Abrir configurações',view:'settings'}];}
 function render(){const all=lessons(),lesson=all[step];root.replaceChildren();const card=document.createElement('div');card.className='guide-card';const kicker=document.createElement('span');kicker.className='eyebrow';kicker.textContent='UM PASSO DE CADA VEZ · '+(step+1)+' / '+all.length;const art=document.createElement('div');art.className='guide-scene';art.setAttribute('aria-hidden','true');art.textContent=lesson.icon;const h=document.createElement('h2');h.textContent=lesson.title;const text=document.createElement('p');text.className='guide-copy';text.textContent=lesson.text;const progress=document.createElement('progress');progress.max=all.length;progress.value=step+1;progress.setAttribute('aria-label','Progresso do guia');const actions=document.createElement('div');actions.className='guide-actions';for(const [label,run,disabled] of [['Anterior',()=>{step--;render();},step===0],[lesson.action,()=>navigate(lesson.view),false],[step===all.length-1?'Recomeçar':'Próximo',()=>{step=(step+1)%all.length;render();},false]]){const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=label;button.disabled=disabled;button.onclick=run;actions.append(button);}card.append(kicker,art,h,text,progress,actions);root.append(card);
 const demo=document.createElement('section');demo.className='card guide-demo';const title=document.createElement('h3');title.textContent='Experimente sem enviar nada';const info=document.createElement('p');info.textContent=['Uma caixa de canetas de exemplo. Clique para adicionar.','Item adicionado ao exemplo. Agora envie a lista de demonstração.','Lista de exemplo em separação. Marque como pronta.','Pronto para retirar! Você completou o fluxo.'][practice];const button=document.createElement('button');button.type='button';button.className='primary';button.textContent=['+ Adicionar item de exemplo','Enviar demonstração','Confirmar exemplo pronto','Experimentar novamente'][practice];button.onclick=()=>{practice=(practice+1)%4;render();};const note=document.createElement('p');note.className='muted small';note.textContent='Simulação educativa: nenhum produto ou pedido real é alterado.';demo.append(title,info,button,note);root.append(demo);}
 return {configure(profile){if(role!==profile?.role){role=profile?.role||'';step=0;practice=0;}render();}};
}
